-- Bloco 7/10: 10 perguntas de O Que é o Espiritismo.
-- Seguro para executar individualmente; não altera perguntas existentes.
INSERT INTO public.questions
  (book, statement, option_a, option_b, option_c, option_d, option_e,
   correct_option, explanation, reference, difficulty, active)
VALUES
  ('o_que_e_espiritismo', 'No início do Capítulo III (''Solução de alguns problemas pela Doutrina Espírita'', item 105), o que ensina o Espiritismo sobre a pluralidade dos mundos?', 'Que todos os globos que circulam no espaço são habitados por seres apropriados à constituição física de cada mundo.', 'Que apenas a Terra e Marte possuem seres vivos inteligentes.', 'Que os astros são apenas pontos luminosos criados para enfeitar a noite terrestre.', 'Que os demais planetas só serão habitados após a destruição da Terra.', 'Que a vida espiritual não pode existir fora da atmosfera terrestre.', 'A', 'No item 105, Kardec expõe que todos os mundos que gravitam no espaço são habitados e apresentam diferentes graus de adiantamento físico e moral.', 'O Que é o Espiritismo - Cap. III, item 105', 'facil', true),
  ('o_que_e_espiritismo', 'Segundo o Capítulo III (itens 106 e 107), qual é a posição da Terra na hierarquia dos mundos habitados?', 'É o mundo mais atrasado e primitivo de todo o universo.', 'Não está na primeira nem na última linha, mas é um dos mundos menos adiantados, onde ainda predominam as provas, expiações e necessidades materiais.', 'É um mundo celeste onde só habitam Espíritos puros.', 'É o único globo onde existe o livre-arbítrio humano.', 'É um planeta superior a Júpiter em evolução moral e física.', 'B', 'Kardec esclarece que a Terra não ocupa nem o primeiro nem o último degrau, mas pertence à categoria dos mundos onde a imperfeição moral e as vicissitudes corporais ainda exigem duro trabalho e expiação.', 'O Que é o Espiritismo - Cap. III, itens 106 e 107', 'expert', true),
  ('o_que_e_espiritismo', 'De acordo com o Capítulo III (''Do homem durante a vida terrestre'', itens 108 a 111), em que momento se completa a união definitiva da alma com o corpo?', 'Apenas aos sete anos de idade, quando começa a razão.', 'Três meses após o batismo religioso da criança.', 'Começa na concepção e só é completa no instante do nascimento.', 'Somente quando o jovem atinge a maioridade civil.', 'Apenas no momento da desencarnação do corpo físico.', 'C', 'No item 110, Kardec precisa que a união da alma com o corpo começa na concepção, mas só se torna completa no momento do nascimento.', 'O Que é o Espiritismo - Cap. III, item 110', 'medio', true),
  ('o_que_e_espiritismo', 'Segundo o Capítulo III (itens 112 e 113), o que ocorre com a alma durante o sono do corpo físico?', 'A alma adormece profundamente e perde toda a atividade consciente.', 'O perispírito dissolve-se temporariamente até o despertar matinal.', 'O Espírito desencarna definitivamente e outro Espírito ocupa o corpo.', 'Os laços que a prendem ao corpo afrouxam-se e a alma recobra parte de sua liberdade, entrando em relação com outros Espíritos nos sonhos.', 'A alma permanece aprisionada exclusivamente dentro do coração.', 'D', 'Enquanto o corpo repousa, o Espírito não precisa de descanso: afrouxam-se os laços fluídicos, ele percorre o espaço e comunica-se com encarnados e desencarnados, originando muitas lembranças de sonhos.', 'O Que é o Espiritismo - Cap. III, itens 112 e 113', 'medio', true),
  ('o_que_e_espiritismo', 'Conforme o Capítulo III (''A alma antes da união com o corpo'', itens 114 e 115), como Deus cria todos os Espíritos?', 'Uns já sábios e virtuosos, e outros predestinados ao mal.', 'Dotados desde o primeiro dia de toda a ciência universal.', 'Divididos em castas eternas que jamais se misturam.', 'Formados a partir da divisão da alma dos próprios pais.', 'Simples e ignorantes, isto é, sem ciência e sem conhecimento do bem e do mal, mas com igual aptidão para tudo adquirir pelo esforço próprio.', 'E', 'Deus, soberanamente justo, não privilegia nenhum Espírito na criação: todos partem do mesmo ponto inicial — simples e ignorantes — e conquistam a perfeição pelo trabalho e livre-arbítrio.', 'O Que é o Espiritismo - Cap. III, itens 114 e 115', 'facil', true),
  ('o_que_e_espiritismo', 'Segundo o Capítulo III (itens 116 a 119), o que faz o Espírito quando abusa de seu livre-arbítrio e retarda seu adiantamento?', 'Sofre as consequências de suas faltas e precisa recomeçar em novas existências corporais a tarefa que desempenhou mal.', 'É condenado ao fogo eterno sem possibilidade de reparação.', 'Regressa à condição de mineral ou vegetal.', 'Perde a individualidade e dissolve-se no fluido cósmico.', 'Recebe o perdão automático no instante da morte sem precisar progredir.', 'A', 'Não podendo ir para os mundos felizes sem haver-se depurado, o Espírito estacionário ou culpado reencarna em mundos de provas e expiações para reparar o tempo perdido.', 'O Que é o Espiritismo - Cap. III, itens 116 a 119', 'medio', true),
  ('o_que_e_espiritismo', 'De acordo com o Capítulo III (''A alma após a morte'', itens 120 a 123), a alma conserva a sua individualidade após a morte do corpo?', 'Não, pois mergulha no todo universal como uma gota d''água no oceano.', 'Sim; jamais a perde, conservando a consciência de si mesma e o envoltório etéreo (perispírito), que reproduz a forma humana.', 'Conserva a individualidade apenas durante quarenta dias após o enterro.', 'Somente os grandes gênios mantêm a memória individual após a morte.', 'A alma divide-se em várias centelhas inconscientes.', 'B', 'Sem individualidade e consciência de si mesma, a sobrevivência seria equivalente ao nada; o Espírito leva consigo o perispírito, sua memória, seus afetos, suas luzes ou sua ignorância.', 'O Que é o Espiritismo - Cap. III, itens 120 a 123', 'facil', true),
  ('o_que_e_espiritismo', 'Segundo o Capítulo III (itens 124 a 127), de que depende a duração e a intensidade da perturbação que se segue à morte?', 'Da riqueza do mausoléu construído pela família na Terra.', 'Da idade cronológica do corpo físico no instante do óbito.', 'Da elevação moral do Espírito e do seu grau de desapego das coisas materiais.', 'Da estação do ano e da fase da Lua no dia do desencarne.', 'Do número de velas acesas ao redor do féretro.', 'C', 'Para o homem de consciência pura, que já se desligou dos interesses terrenos durante a vida, o despertar espiritual é rápido e calmo; para o materialista e o culpado, a perturbação é longa e penosa.', 'O Que é o Espiritismo - Cap. III, itens 124 a 127', 'expert', true),
  ('o_que_e_espiritismo', 'No Capítulo III (''Estado dos Espíritos'', itens 128 a 132), como são chamados os Espíritos que se encontram no intervalo entre duas existências corporais?', 'Espíritos elementais.', 'Espíritos cristalizados.', 'Espíritos incriados.', 'Espíritos errantes (no estado de erraticidade).', 'Espíritos anônimos.', 'D', 'No item 128, Kardec explica que no intervalo de suas existências corporais os Espíritos estão no estado de erraticidade e são denominados Espíritos errantes.', 'O Que é o Espiritismo - Cap. III, item 128', 'facil', true),
  ('o_que_e_espiritismo', 'De acordo com o Capítulo III (itens 129 e 130), todos os Espíritos desencarnados permanecem errantes indefinidamente?', 'Sim, todos os Espíritos continuam errantes por toda a eternidade.', 'Sim, pois nenhum Espírito jamais fica livre da reencarnação.', 'Não, porque após três séculos os Espíritos deixam de existir.', 'Apenas os Espíritos inferiores deixam de ser errantes.', 'Não; os Espíritos puros, que atingiram a perfeição e não precisam mais de novas reencarnações, não são mais errantes, pois seu estado é definitivo.', 'E', 'O estado errante é transitório e próprio dos Espíritos que ainda têm de reencarnar para progredir; os Espíritos puros já chegaram ao termo da escala e gozam da felicidade definitiva.', 'O Que é o Espiritismo - Cap. III, itens 129 e 130', 'medio', true)
ON CONFLICT (statement) DO NOTHING;

SELECT COUNT(*) AS perguntas_do_livro
FROM public.questions
WHERE book = 'o_que_e_espiritismo';